import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { X, ChevronLeft, ChevronRight, ZoomIn } from 'lucide-react';
import SEO from '../components/SEO';

const EventGallery = () => {
    const { t } = useTranslation();
    const [filter, setFilter] = useState('all');
    const [selectedImage, setSelectedImage] = useState(null);

    // Categories: all, medical, community, awareness
    const categories = [
        { id: 'all', label: t('gallery.filters.all') },
        { id: 'medical', label: t('gallery.filters.medical') },
        { id: 'community', label: t('gallery.filters.community') },
        { id: 'awareness', label: t('gallery.filters.awareness') },
    ];

    const allEvents = [
        {
            id: 1,
            title: 'Free Checkup Camp',
            date: '2024-01-15',
            category: 'medical',
            image: 'https://images.unsplash.com/photo-1576201836106-db1758fd1c97?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 2,
            title: 'Gaushala Visit',
            date: '2024-02-01',
            category: 'community',
            image: 'https://images.unsplash.com/photo-1545648682-9653063f915f?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 3,
            title: 'Vaccination Drive',
            date: '2024-03-10',
            category: 'medical',
            image: 'https://images.unsplash.com/photo-1628009368231-7603352721c8?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 4,
            title: 'Awareness Seminar',
            date: '2024-04-05',
            category: 'awareness',
            image: 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 5,
            title: 'Community Meeting',
            date: '2024-04-20',
            category: 'community',
            image: 'https://images.unsplash.com/photo-1511632765486-a01980e01a18?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 6,
            title: 'New Equipment Launch',
            date: '2024-05-12',
            category: 'medical',
            image: 'https://images.unsplash.com/photo-1581093458791-9f3c3900df4b?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 7,
            title: 'Farmer Training',
            date: '2024-06-15',
            category: 'awareness',
            image: 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&q=80&w=800',
        },
        {
            id: 8,
            title: 'Calf Rally',
            date: '2024-07-20',
            category: 'community',
            image: 'https://images.unsplash.com/photo-1500595046743-cd271d694d30?auto=format&fit=crop&q=80&w=800',
        }
    ];

    const filteredEvents = filter === 'all'
        ? allEvents
        : allEvents.filter(event => event.category === filter);

    const openLightbox = (image) => {
        setSelectedImage(image);
        document.body.style.overflow = 'hidden';
    };

    const closeLightbox = () => {
        setSelectedImage(null);
        document.body.style.overflow = 'unset';
    };

    const nextImage = (e) => {
        e.stopPropagation();
        const currentIndex = filteredEvents.findIndex(ev => ev.id === selectedImage.id);
        const nextIndex = (currentIndex + 1) % filteredEvents.length;
        setSelectedImage(filteredEvents[nextIndex]);
    };

    const prevImage = (e) => {
        e.stopPropagation();
        const currentIndex = filteredEvents.findIndex(ev => ev.id === selectedImage.id);
        const prevIndex = (currentIndex - 1 + filteredEvents.length) % filteredEvents.length;
        setSelectedImage(filteredEvents[prevIndex]);
    };

    return (
        <main className="pt-24 pb-16 min-h-screen bg-stone-50">
            <SEO
                title="Event Gallery"
                description="Explore glimpses of Vetnmark's recent activities, medical camps, awareness programs, and community events dedicated to indigenous cattle."
            />
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                {/* Header Section */}
                <div
                    className="text-center mb-16 transition-all duration-500"
                >
                    <h1 className="text-4xl md:text-6xl font-serif font-bold text-stone-800 mb-6 relative inline-block">
                        {t('gallery.title', 'Event Gallery')}
                        <span className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-24 h-1 bg-green-600 rounded-full"></span>
                    </h1>
                    <p className="text-lg md:text-xl text-stone-600 max-w-2xl mx-auto leading-relaxed">
                        {t('gallery.subtitle', 'Glimpses of our recent activities, camps, and community events.')}
                    </p>
                </div>

                {/* Filter Tabs */}
                <div className="flex flex-wrap justify-center gap-4 mb-12">
                    {categories.map((cat) => (
                        <button
                            key={cat.id}
                            onClick={() => setFilter(cat.id)}
                            className={`px-6 py-2 rounded-full text-sm font-semibold transition-all duration-300 transform hover:scale-105 ${filter === cat.id
                                ? 'bg-green-700 text-white shadow-lg shadow-green-200'
                                : 'bg-white text-stone-600 hover:bg-green-50 border border-stone-200'
                                }`}
                        >
                            {cat.label}
                        </button>
                    ))}
                </div>

                {/* Masonry Grid */}
                <div
                    className="columns-1 md:columns-2 lg:columns-3 gap-8 space-y-8"
                >

                    {filteredEvents.map((event) => (
                        <div
                            key={event.id}
                            className="break-inside-avoid group relative rounded-2xl overflow-hidden shadow-md hover:shadow-2xl transition-all duration-500 cursor-pointer bg-white"
                            onClick={() => openLightbox(event)}
                        >
                            <img
                                src={event.image}
                                alt={event.title}
                                className="w-full h-auto object-cover transform group-hover:scale-110 transition-transform duration-700"
                            />
                            {/* Overlay Gradient */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-6">
                                <span className="inline-block px-3 py-1 bg-green-600 text-white text-xs font-bold rounded-full mb-2 w-fit transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-100">
                                    {categories.find(c => c.id === event.category)?.label}
                                </span>
                                <h3 className="text-xl font-bold text-white transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-150">
                                    {event.title}
                                </h3>
                                <p className="text-gray-300 text-sm mt-1 transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-200">
                                    {event.date}
                                </p>
                                <div className="absolute top-4 right-4 bg-white/20 backdrop-blur-sm p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all duration-300 delay-300 hover:bg-white/40">
                                    <ZoomIn className="w-5 h-5 text-white" />
                                </div>
                            </div>
                        </div>
                    ))}

                </div>
            </div>

            {/* Lightbox Modal */}

            {selectedImage && (
                <div
                    className="fixed inset-0 z-[60] bg-black/95 backdrop-blur-sm flex items-center justify-center p-4 transition-all duration-300"
                    onClick={closeLightbox}
                >
                    {/* Close Button */}
                    <button
                        onClick={closeLightbox}
                        className="absolute top-6 right-6 text-white/70 hover:text-white transition-colors p-2 bg-white/10 rounded-full hover:bg-white/20"
                    >
                        <X className="w-8 h-8" />
                    </button>

                    {/* Navigation Buttons */}
                    <button onClick={prevImage} className="absolute left-4 md:left-8 text-white/70 hover:text-white p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all">
                        <ChevronLeft className="w-8 h-8" />
                    </button>
                    <button onClick={nextImage} className="absolute right-4 md:right-8 text-white/70 hover:text-white p-3 bg-white/10 rounded-full hover:bg-white/20 transition-all">
                        <ChevronRight className="w-8 h-8" />
                    </button>

                    {/* Image Container */}
                    <div
                        className="relative max-w-5xl w-full max-h-[85vh] flex flex-col items-center transition-all duration-300"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <img
                            src={selectedImage.image}
                            alt={selectedImage.title}
                            className="max-w-full max-h-[80vh] object-contain rounded-lg shadow-2xl"
                        />
                        <div className="mt-4 text-center">
                            <h3 className="text-2xl font-bold text-white mb-1">
                                {selectedImage.title}
                            </h3>
                            <p className="text-gray-400">
                                {selectedImage.date} ΓÇó {categories.find(c => c.id === selectedImage.category)?.label}
                            </p>
                        </div>
                    </div>
                </div>
            )}

        </main>
    );
};

export default EventGallery;
